(async () => {
const assert = require('node:assert');

const { createEmitter } = require(require('node:path').resolve('events.js'));
const e = createEmitter(); const log = [];
e.on('x', () => log.push(1)); e.on('x', () => { throw new Error('boom'); }); e.on('x', () => log.push(3));
let threw = false; try { e.emit('x'); } catch { threw = true; }
assert.strictEqual(threw, false, 'emit must not throw'); assert.deepStrictEqual(log, [1, 3], 'synchronous, in order, errors isolated');
e.once('y', () => log.push('y')); e.emit('y'); e.emit('y'); assert.strictEqual(log.filter((v) => v === 'y').length, 1);
const h = () => log.push('z'); e.on('z', h); e.off('z', h); e.emit('z'); assert.ok(!log.includes('z'));
})().catch((e) => { console.error(e && e.stack || e); process.exit(1); });
